using System.ComponentModel;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// ---------------------------------------------------------------------------
// Research Agent – searches the web, takes notes, and summarises findings.
// ---------------------------------------------------------------------------

string topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Build the tools the agent can call ----
var researchTools = new ResearchTools();
List<AITool> tools =
[
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.AddNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
];

// --- Create the inner chat-client agent ----
IChatClient chatClient = new ChatClientBuilder(
        new OpenAI.OpenAIClient(
            Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "test-key")
        .GetChatClient("gpt-4o")
        .AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. Given a topic you MUST:
        1. Use the SearchWeb tool multiple times with different queries to gather
           information from varied angles.
        2. Use the AddNote tool to save each key finding as a short note.
        3. Use GetNotes to review everything you have collected.
        4. After you have gathered enough information (at least 3 searches),
           produce a concise summary in markdown with sections:
             ## Key Findings
             ## Details
             ## Sources
        Be thorough but concise. Always cite search queries used.
        """,
    name: "ResearchAgent",
    description: "Researches a topic by searching the web and summarising findings.",
    tools: tools);

// --- Run the agent in a loop (max 10 iterations) ----
var loopAgent = new LoopAgent(
    agent,
    new CompletionMarkerLoopEvaluator(new CompletionMarkerLoopEvaluatorOptions
    {
        Markers = ["## Sources"],
    }),
    new LoopAgentOptions { MaxIterations = 10 });

var session = await loopAgent.CreateSessionAsync();
AgentResponse response = await loopAgent.RunAsync(topic, session);

Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine(response.Text);
Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine($"\n📝 Notes collected: {researchTools.NoteCount}");

// ---------------------------------------------------------------------------
// Helper
// ---------------------------------------------------------------------------
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    string? input = Console.ReadLine();
    return string.IsNullOrWhiteSpace(input)
        ? "recent advances in quantum computing"
        : input;
}

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
sealed class ResearchTools
{
    private static readonly HttpClient s_http = new();
    private readonly List<string> _notes = [];

    public int NoteCount => _notes.Count;

    [Description("Search the web for information on a query. Returns a list of results with titles, snippets, and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            string encoded = Uri.EscapeDataString(query);
            string url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.Add("User-Agent", "ResearchAgent/1.0");

            var resp = await s_http.SendAsync(request);
            resp.EnsureSuccessStatusCode();

            using var doc = await JsonDocument.ParseAsync(await resp.Content.ReadAsStreamAsync());
            var root = doc.RootElement;

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"\n");

            // Abstract
            string abstractText = root.GetProperty("AbstractText").GetString() ?? "";
            string abstractUrl = root.GetProperty("AbstractURL").GetString() ?? "";
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                sb.AppendLine($"**Summary**: {abstractText}");
                sb.AppendLine($"**Source**: {abstractUrl}\n");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                int count = 0;
                foreach (var item in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    string text = item.TryGetProperty("Text", out var t) ? t.GetString() ?? "" : "";
                    string link = item.TryGetProperty("FirstURL", out var u) ? u.GetString() ?? "" : "";
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        sb.AppendLine($"- {text}");
                        if (!string.IsNullOrWhiteSpace(link))
                            sb.AppendLine($"  URL: {link}");
                        count++;
                    }
                }
            }

            string result = sb.ToString();
            return string.IsNullOrWhiteSpace(result.Trim())
                ? $"No detailed results found for \"{query}\". Try a different query."
                : result;
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record key findings during research.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📌 Note #{_notes.Count} saved");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes to review findings so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"All notes ({_notes.Count} total):\n");
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"{i + 1}. {_notes[i]}");
        return sb.ToString();
    }
}

