 using System.ComponentModel;
 using System.Net.Http.Json;
 using System.Text;
 using System.Text.Json;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;

 // ---------------------------------------------------------------------------
 // Research Agent – searches the web, takes notes, and summarises findings.
 // ---------------------------------------------------------------------------

 string topic = args.Length > 0
     ? string.Join(' ', args)
     : PromptForTopic();

 Console.WriteLine($"\n🔍 Researching: {topic}\n");

 // --- Build the tools the agent can call ----
 var researchTools = new ResearchTools();
 List<AITool> tools =
 [
     AIFunctionFactory.Create(researchTools.SearchWeb),
     AIFunctionFactory.Create(researchTools.AddNote),
     AIFunctionFactory.Create(researchTools.GetNotes),
 ];

 // --- Create the inner chat-client agent ----
 IChatClient chatClient = new ChatClientBuilder(
         new OpenAI.OpenAIClient(
             Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "test-key")
         .GetChatClient("gpt-4o")
         .AsIChatClient())
     .UseFunctionInvocation()
     .Build();

 var agent = new ChatClientAgent(
     chatClient,
     instructions: """
         You are a research assistant. Given a topic you MUST:
         1. Use the SearchWeb tool multiple times with different queries to gather
            information from varied angles.
         2. Use the AddNote tool to save each key finding as a short note.
         3. Use GetNotes to review everything you have collected.
         4. After you have gathered enough information (at least 3 searches),
            produce a concise summary in markdown with sections:
              ## Key Findings
              ## Details
              ## Sources
         Be thorough but concise. Always cite search queries used.
         """,
     name: "ResearchAgent",
     description: "Researches a topic by searching the web and summarising findings.",
     tools: tools);

 // --- Run the agent in a loop (max 10 iterations) ----
 var loopAgent = new LoopAgent(
     agent,
     new CompletionMarkerLoopEvaluator("## Sources"),
     new LoopAgentOptions { MaxIterations = 10 });

