 // ---------------------------------------------------------------------------
 sealed class ResearchTools
 {
     private static readonly HttpClient s_http = new();
     private readonly List<string> _notes = [];

     public int NoteCount => _notes.Count;

     [Description("Search the web for information on a query. Returns a list of results with titles, snippets, and URLs.")]
     public async Task<string> SearchWeb(
         [Description("The search query string")] string query)
     {
         Console.WriteLine($"  🌐 Searching: \"{query}\"");

         try
         {
             // Use DuckDuckGo Instant Answer API (no key required)
             string encoded = Uri.EscapeDataString(query);
             string url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

             using var request = new HttpRequestMessage(HttpMethod.Get, url);
             request.Headers.Add("User-Agent", "ResearchAgent/1.0");

             var resp = await s_http.SendAsync(request);
             resp.EnsureSuccessStatusCode();

             using var doc = await JsonDocument.ParseAsync(await resp.Content.ReadAsStreamAsync());
             var root = doc.RootElement;

             var sb = new StringBuilder();
             sb.AppendLine($"Search results for: \"{query}\"\n");

             // Abstract
             string abstractText = root.GetProperty("AbstractText").GetString() ?? "";
             string abstractUrl = root.GetProperty("AbstractURL").GetString() ?? "";
             if (!string.IsNullOrWhiteSpace(abstractText))
             {
                 sb.AppendLine($"**Summary**: {abstractText}");
                 sb.AppendLine($"**Source**: {abstractUrl}\n");
             }

             // Related topics
             if (root.TryGetProperty("RelatedTopics", out var topics))
             {
                 int count = 0;
                 foreach (var item in topics.EnumerateArray())
                 {
                     if (count >= 5) break;
                     string text = item.TryGetProperty("Text", out var t) ? t.GetString() ?? "" : "";
                     string link = item.TryGetProperty("FirstURL", out var u) ? u.GetString() ?? "" : "";
                     if (!string.IsNullOrWhiteSpace(text))
                     {
                         sb.AppendLine($"- {text}");
                         if (!string.IsNullOrWhiteSpace(link))
                             sb.AppendLine($"  URL: {link}");
                         count++;
                     }
                 }
             }

             string result = sb.ToString();
             return string.IsNullOrWhiteSpace(result.Trim())
                 ? $"No detailed results found for \"{query}\". Try a different query."
                 : result;
         }
         catch (Exception ex)
         {
             return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
         }
     }

     [Description("Save a research note. Use this to record key findings during research.")]
     public string AddNote(
         [Description("The note content to save")] string note)
     {
         _notes.Add(note);
         Console.WriteLine($"  📌 Note #{_notes.Count} saved");
         return $"Note #{_notes.Count} saved successfully.";
     }

     [Description("Retrieve all saved research notes to review findings so far.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         var sb = new StringBuilder();
         sb.AppendLine($"All notes ({_notes.Count} total):\n");
         for (int i = 0; i < _notes.Count; i++)
             sb.AppendLine($"{i + 1}. {_notes[i]}");
         return sb.ToString();
     }
 }

