             return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
         }
     }

     [Description("Save a research note. Use this to record key findings during research.")]
     public string AddNote(
         [Description("The note content to save")] string note)
     {
         _notes.Add(note);
         Console.WriteLine($"  📌 Note #{_notes.Count} saved");
         return $"Note #{_notes.Count} saved successfully.";
     }

     [Description("Retrieve all saved research notes to review findings so far.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         var sb = new StringBuilder();
         sb.AppendLine($"All notes ({_notes.Count} total):\n");
         for (int i = 0; i < _notes.Count; i++)
             sb.AppendLine($"{i + 1}. {_notes[i]}");
         return sb.ToString();
     }
 }
